package com.projetok.studio;
import javax.swing.*;
import java.awt.*;
import java.util.*;

/** Cadastro visual de indices de recortes para as dezesseis mascaras NESW. */
final class TerrainTools {
    TerrainTools(WorldStudio ui){ui.action("Terrenos","Cadastrar regra autotile",()->{if(ui.brush==null||ui.tilesetCrops.isEmpty())throw new IllegalArgumentException("Selecione recortes em Recortar tileset primeiro");JPanel form=new JPanel(new BorderLayout());JTextField id=new JTextField("terreno");form.add(id,BorderLayout.NORTH);JTextArea mappings=new JTextArea("0=-1\n1=-1\n2=-1\n3=-1\n4=-1\n5=-1\n6=-1\n7=-1\n8=-1\n9=-1\n10=-1\n11=-1\n12=-1\n13=-1\n14=-1\n15=-1",16,30);form.add(new JScrollPane(mappings));form.add(new JLabel("Mascara=indice do recorte (ordem de leitura, inicia 0). -1: fallback explicito."),BorderLayout.SOUTH);if(JOptionPane.showConfirmDialog(ui,form,"NESW: 1=N, 2=E, 4=S, 8=W",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;Map<Integer,WorldDocument.Crop> rules=new HashMap<>();for(String line:mappings.getText().split("\n")){var parts=line.split("=");int mask=Integer.parseInt(parts[0]),index=Integer.parseInt(parts[1]);if(index>=0){if(index>=ui.tilesetCrops.size())throw new IllegalArgumentException("Indice inexistente");rules.put(mask,ui.tilesetCrops.get(index));}}ui.change(Autotiling.register(ui.document,new Autotiling.Rule(id.getText(),ui.brush.id(),ui.brush.sha(),ui.brushCrop,rules)));ui.activeTerrain=id.getText();});ui.action("Terrenos","Ativar terreno",()->{String id=(String)JOptionPane.showInputDialog(ui,"Terreno","Paleta",JOptionPane.PLAIN_MESSAGE,null,Autotiling.terrains(ui.document).toArray(String[]::new),null);if(id!=null)ui.activeTerrain=id;});ui.action("Terrenos","Desativar autotile",()->{ui.activeTerrain="";ui.status.setText("Pintura manual ativa");});}
}
